'use client';

import { useEffect, useId, useMemo, useRef, useState, type CSSProperties } from 'react';
import './signal-funnel.css';

export interface SignalFunnelGate {
  id: string;
  label: string;
}

export interface SignalFunnelProps {
  /** One to five stages. Duplicate or empty ids are ignored. An empty array removes all stages. */
  gates?: readonly SignalFunnelGate[];
  enabledGateIds?: readonly string[];
  defaultEnabledGateIds?: readonly string[];
  onGatesChange?: (enabledIds: string[]) => void;
  inputLabel?: string;
  outputLabel?: string;
  accent?: string;
  /** Stops motion externally. The built-in pause control is disabled while true. */
  paused?: boolean;
  className?: string;
}

const DEFAULT_GATES: readonly SignalFunnelGate[] = [
  { id: 'redact', label: 'Redact' },
  { id: 'validate', label: 'Validate' },
  { id: 'encrypt', label: 'Encrypt' },
];

function noise(value: number) {
  const n = Math.sin(value * 12.9898 + 78.233) * 43758.5453;
  return n - Math.floor(n);
}

/** An illustrative event pipeline. Stage switches alter the visualization; they do not process data. */
export function SignalFunnel({
  gates = DEFAULT_GATES,
  enabledGateIds,
  defaultEnabledGateIds,
  onGatesChange,
  inputLabel = 'Incoming events',
  outputLabel = 'Processed events',
  accent = '#7950f2',
  paused = false,
  className = '',
}: SignalFunnelProps) {
  const titleId = useId();
  const stageRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const elapsedRef = useRef(0);
  const [localPaused, setLocalPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const [ready, setReady] = useState(false);
  const validGates = useMemo(() => {
    const seen = new Set<string>();
    return gates.filter((gate) => {
      if (!gate.id.trim() || seen.has(gate.id)) return false;
      seen.add(gate.id);
      return true;
    }).slice(0, 5);
  }, [gates]);
  const [internalIds, setInternalIds] = useState<string[]>(() =>
    [...(defaultEnabledGateIds ?? validGates.map((gate) => gate.id))],
  );
  const ids = enabledGateIds ?? internalIds;
  const enabled = validGates.map((gate) => ids.includes(gate.id));
  const enabledKey = enabled.map((value) => value ? '1' : '0').join('');
  const enabledCount = enabled.filter(Boolean).length;
  const isPaused = paused || localPaused;

  useEffect(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;
    const context = canvas.getContext('2d');
    if (!context) return;
    setReady(true);
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    const activeGates = [...enabledKey].map((value) => value === '1');
    let width = 0;
    let height = 0;
    let particleColor = accent;
    let inkColor = '#34372e';
    let inView = true;
    let frame: number | null = null;
    let lastTime: number | null = null;
    let lastPaint = 0;
    let disposed = false;

    function draw(time: number) {
      if (!context || !canvas || !width || !height) return;
      context.clearRect(0, 0, width, height);
      const vertical = width < 600;
      const point = (u: number, v: number): [number, number] => vertical
        ? [width * (0.5 + v * 0.9), height * (0.08 + u * 0.84)]
        : [width * (0.035 + u * 0.93), height * (0.5 + v)];
      const positions = activeGates.map((_, index) => activeGates.length === 1 ? 0.46 : 0.24 + index * 0.44 / (activeGates.length - 1));
      const anchors: [number, number][] = [[0, 0.34]];
      let radius = 0.34;
      positions.forEach((position, index) => {
        if (activeGates[index]) radius *= 0.55;
        anchors.push([position, radius]);
      });
      anchors.push([0.80, activeGates.every(Boolean) ? 0.001 : Math.max(0.026, radius * 0.5)]);
      const radiusAt = (u: number) => {
        for (let i = 1; i < anchors.length; i++) {
          if (u <= anchors[i][0]) {
            const [start, first] = anchors[i - 1];
            const [end, second] = anchors[i];
            return first + (second - first) * (u - start) / (end - start);
          }
        }
        return anchors[anchors.length - 1][1];
      };
      const columns = vertical ? 80 : Math.min(145, Math.max(90, Math.floor(width / 7)));
      const rows = vertical ? 65 : 72;
      context.fillStyle = particleColor;
      for (let col = 0; col < columns; col++) {
        const u = ((col / columns + time * 0.038) % 1) * 0.8;
        const cone = radiusAt(u);
        for (let row = 0; row < rows; row++) {
          const seed = col * rows + row;
          if (noise(seed * 1.37) < 0.14) continue;
          const band = (row / (rows - 1) - 0.5) * 2;
          const sway = Math.sin(u * 18 - time * 1.2 + row * 0.45) * 0.008;
          const v = band * cone + sway * (1 - u);
          const [x, y] = point(u, v);
          const edge = 1 - Math.pow(Math.abs(band), 2);
          context.globalAlpha = 0.18 + edge * 0.60 + noise(seed + Math.floor(time * 2)) * 0.13;
          const dot = noise(seed + 61) > 0.97 ? 2.2 : 1.35;
          if (noise(seed + 31) > 0.97) {
            context.fillRect(x - 2, y, 4, 1);
            context.fillRect(x, y - 2, 1, 4);
          } else {
            context.fillRect(Math.round(x), Math.round(y), dot, dot);
          }
        }
      }
      // A handful of rejected packets peel away at enabled gates.
      positions.forEach((position, index) => {
        if (!activeGates[index]) return;
        for (let packet = 0; packet < 5; packet++) {
          const phase = (time * 0.34 + packet / 5 + index * 0.17) % 1;
          const distance = phase * 0.14;
          const [x, y] = point(position - 0.008 - distance * 0.18, radiusAt(position) + distance);
          context.globalAlpha = (1 - phase) * 0.7;
          context.fillRect(x, y, 2.3, 2.3);
        }
      });
      context.globalAlpha = 1;
      // The outgoing rail is intentionally quieter than the incoming field.
      context.strokeStyle = inkColor;
      context.lineWidth = 1;
      context.beginPath();
      const [railX, railY] = point(0.8, 0);
      const [endX, endY] = point(1, 0);
      context.moveTo(railX, railY);
      context.lineTo(endX, endY);
      context.stroke();
      context.fillStyle = particleColor;
      for (let i = 0; i < 3; i++) {
        const u = 0.8 + ((time * 0.14 + i / 3) % 1) * 0.2;
        const [x, y] = point(u, 0);
        context.fillRect(x - 2.5, y - 2.5, 5, 5);
      }
      context.fillStyle = inkColor;
      context.fillRect(endX - 5, endY - 5, 10, 10);
    }

    function cancel() {
      if (frame !== null) window.cancelAnimationFrame(frame);
      frame = null;
      lastTime = null;
    }
    function canAnimate() {
      return !disposed && !isPaused && !media.matches && !document.hidden && inView;
    }
    function tick(now: number) {
      frame = null;
      if (!canAnimate()) { lastTime = null; return; }
      if (lastTime !== null) elapsedRef.current += Math.min((now - lastTime) / 1000, 0.05);
      lastTime = now;
      if (now - lastPaint >= 1000 / 30) {
        draw(elapsedRef.current);
        lastPaint = now;
      }
      frame = window.requestAnimationFrame(tick);
    }
    function synchronize() {
      cancel();
      draw(elapsedRef.current);
      if (canAnimate()) frame = window.requestAnimationFrame(tick);
    }
    function refreshColors() {
      particleColor = window.getComputedStyle(stage!).color || accent;
      inkColor = stage!.parentElement ? window.getComputedStyle(stage!.parentElement).color : '#34372e';
      draw(elapsedRef.current);
    }
    function resize() {
      if (!canvas || !stage) return;
      width = stage.clientWidth;
      height = stage.clientHeight;
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
      context?.setTransform(ratio, 0, 0, ratio, 0, 0);
      refreshColors();
    }
    function onPreferenceChange() {
      setReducedMotion(media.matches);
      synchronize();
    }
    const resizeObserver = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(resize) : null;
    const intersectionObserver = typeof IntersectionObserver !== 'undefined' ? new IntersectionObserver(([entry]) => {
      inView = entry?.isIntersecting ?? true;
      synchronize();
    }, { threshold: 0 }) : null;
    resizeObserver?.observe(stage);
    intersectionObserver?.observe(stage);
    const themeObserver = typeof MutationObserver === 'undefined' ? null : new MutationObserver(refreshColors);
    for (let ancestor: HTMLElement | null = stage; ancestor; ancestor = ancestor.parentElement) {
      themeObserver?.observe(ancestor, { attributes: true, attributeFilter: ['data-theme', 'class'] });
    }
    window.addEventListener('resize', resize);
    document.addEventListener('visibilitychange', synchronize);
    media.addEventListener('change', onPreferenceChange);
    resize();
    onPreferenceChange();
    return () => {
      disposed = true;
      cancel();
      resizeObserver?.disconnect();
      intersectionObserver?.disconnect();
      themeObserver?.disconnect();
      window.removeEventListener('resize', resize);
      document.removeEventListener('visibilitychange', synchronize);
      media.removeEventListener('change', onPreferenceChange);
    };
  }, [accent, enabledKey, isPaused]);

  function toggleGate(id: string) {
    const next = validGates.filter((gate) => gate.id === id ? !ids.includes(gate.id) : ids.includes(gate.id)).map((gate) => gate.id);
    if (enabledGateIds === undefined) setInternalIds(next);
    onGatesChange?.(next);
  }

  return (
    <section className={`ac-signal-funnel ${className}`} aria-labelledby={titleId} style={{ '--ac-signal-accent': accent } as CSSProperties} data-motion={reducedMotion ? 'reduced' : isPaused ? 'paused' : 'running'}>
      <header className="ac-signal-funnel__header">
        <h2 id={titleId}><span aria-hidden="true">↳</span> Signal pipeline</h2>
        <button className="ac-signal-funnel__motion" type="button" disabled={reducedMotion || paused} onClick={() => setLocalPaused((value) => !value)}>
          <span aria-hidden="true">{isPaused || reducedMotion ? '▷' : 'Ⅱ'}</span>
          {reducedMotion ? 'Reduced motion' : paused ? 'Motion paused' : localPaused ? 'Play motion' : 'Pause motion'}
        </button>
      </header>
      <div className="ac-signal-funnel__stage" ref={stageRef} data-ready={ready || undefined} data-gates={validGates.length}>
        <div className="ac-signal-funnel__fallback" aria-hidden="true" />
        <canvas ref={canvasRef} aria-hidden="true" />
        <span className="ac-signal-funnel__input">{inputLabel}</span>
        {validGates.map((gate, index) => {
          const position = validGates.length === 1 ? 0.46 : 0.24 + index * 0.44 / (validGates.length - 1);
          return <div key={gate.id} className="ac-signal-funnel__gate" data-enabled={enabled[index]} data-order={index} style={{ '--gate-x': `${(0.035 + position * 0.93) * 100}%`, '--gate-y': `${(0.08 + position * 0.84) * 100}%` } as CSSProperties}>
            <span className="ac-signal-funnel__gate-line" aria-hidden="true" />
            <button type="button" aria-pressed={enabled[index]} onClick={() => toggleGate(gate.id)} title={`${enabled[index] ? 'Bypass' : 'Enable'} ${gate.label}`}>
              <span className="ac-signal-funnel__gate-number" aria-hidden="true">0{index + 1}</span>
              <span className="ac-signal-funnel__gate-label">{gate.label}</span>
              <span className="ac-signal-funnel__gate-check" aria-hidden="true">{enabled[index] ? '✓' : '−'}</span>
            </button>
          </div>;
        })}
        <span className="ac-signal-funnel__output">{outputLabel}</span>
        {enabledCount > 0 && <span className="ac-signal-funnel__removed" aria-hidden="true"><span /> Filtered</span>}
      </div>
      <footer className="ac-signal-funnel__footer">
        <span><i aria-hidden="true" />{enabledCount} / {validGates.length} stages enabled</span>
        {validGates.length > 0 && <span>Toggle a stage to change the flow</span>}
      </footer>
      <span className="ac-signal-funnel__sr" role="status">{enabledCount} of {validGates.length} stages enabled. {validGates.map((gate, index) => `${gate.label}: ${enabled[index] ? 'enabled' : 'bypassed'}`).join('. ')}. Illustrative event flow.</span>
    </section>
  );
}

.ac-signal-funnel{--ac-signal-accent:#7950f2;--ac-signal-ink:#34372e;--ac-signal-muted:#77776e;--ac-signal-line:#deddd7;--ac-signal-surface:#faf9f6;container-type:inline-size;position:relative;isolation:isolate;width:100%;min-width:0;overflow:hidden;border:1px solid var(--ac-signal-line);background:var(--ac-signal-surface);color:var(--ac-signal-ink);font-family:Arial,Helvetica,sans-serif;text-align:left;box-sizing:border-box}
.ac-signal-funnel *{box-sizing:border-box}
.ac-signal-funnel__header{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:66px;padding:16px 24px;border-bottom:1px solid var(--ac-signal-line)}
.ac-signal-funnel__header h2{display:flex;align-items:center;gap:11px;margin:0;font:500 13px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:-.025em}
.ac-signal-funnel__header h2>span{font-size:22px;color:var(--ac-signal-accent)}
.ac-signal-funnel button{color:inherit;cursor:pointer;font:inherit;border-radius:0;-webkit-tap-highlight-color:transparent}
.ac-signal-funnel button:focus-visible{outline:2px solid var(--ac-signal-accent);outline-offset:5px}
.ac-signal-funnel__motion{display:flex;align-items:center;gap:7px;padding:7px 0;border:0;background:transparent;font:10px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace!important;white-space:nowrap;color:var(--ac-signal-muted)!important}
.ac-signal-funnel__motion>span{font-size:13px;color:var(--ac-signal-ink)}
.ac-signal-funnel__motion:disabled{cursor:default;opacity:.7}
.ac-signal-funnel__stage{position:relative;width:100%;height:clamp(330px,40cqi,460px);overflow:hidden;color:var(--ac-signal-accent);background-image:radial-gradient(circle,color-mix(in srgb,var(--ac-signal-accent) 20%,transparent) .6px,transparent .8px);background-size:7px 7px}
.ac-signal-funnel__stage canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.ac-signal-funnel__fallback{position:absolute;inset:10% 21% 10% 3%;clip-path:polygon(0 0,100% 49.5%,100% 50.5%,0 100%);opacity:.7;background-image:radial-gradient(circle,var(--ac-signal-accent) 1px,transparent 1.2px);background-size:5px 5px}
.ac-signal-funnel__stage[data-ready=true] .ac-signal-funnel__fallback{display:none}
.ac-signal-funnel__input,.ac-signal-funnel__output{position:absolute;z-index:2;padding:5px 7px;background:var(--ac-signal-surface);font:9px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;text-transform:uppercase;letter-spacing:.04em;max-width:160px;overflow-wrap:anywhere}
.ac-signal-funnel__input{top:16px;left:19px;color:var(--ac-signal-muted)}
.ac-signal-funnel__output{top:calc(50% + 20px);right:18px;border:1px solid #aaa99f;color:var(--ac-signal-ink)}
.ac-signal-funnel__gate{position:absolute;z-index:3;left:var(--gate-x);top:18%;bottom:18%;width:0;color:var(--ac-signal-ink)}
.ac-signal-funnel__gate-line{position:absolute;inset:0 auto 0 0;border-left:1px solid #747368;transition:border-color .2s}
.ac-signal-funnel__gate-line:before,.ac-signal-funnel__gate-line:after{content:"";position:absolute;left:-4px;width:7px;height:7px;border:1px solid #858377;background:#e7ddff}
.ac-signal-funnel__gate-line:before{top:0}.ac-signal-funnel__gate-line:after{bottom:0}
.ac-signal-funnel__gate button{position:absolute;bottom:calc(100% + 14px);left:0;display:flex;align-items:center;gap:8px;transform:translateX(-50%);padding:7px 10px;border:1px solid transparent;background:#ddd0ff;font:10px/1.3 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:nowrap;transition:background .2s,border-color .2s}
.ac-signal-funnel__gate button:hover{border-color:var(--ac-signal-accent)}
.ac-signal-funnel__gate-number{font-size:8px;opacity:.6}
.ac-signal-funnel__gate-check{min-width:8px;font-size:10px}
.ac-signal-funnel__gate-label{display:block;min-width:0;max-width:140px;overflow:hidden;text-overflow:ellipsis}
.ac-signal-funnel__stage:is([data-gates="4"],[data-gates="5"]) .ac-signal-funnel__gate:is([data-order="1"],[data-order="3"]) button{bottom:auto;top:calc(100% + 14px)}
.ac-signal-funnel__gate[data-enabled=false] button{border-color:var(--ac-signal-line);background:var(--ac-signal-surface);color:var(--ac-signal-muted)}
.ac-signal-funnel__gate[data-enabled=false] .ac-signal-funnel__gate-line{border-left-style:dashed;opacity:.45}
.ac-signal-funnel__gate[data-enabled=false] .ac-signal-funnel__gate-line:before,.ac-signal-funnel__gate[data-enabled=false] .ac-signal-funnel__gate-line:after{background:var(--ac-signal-surface)}
.ac-signal-funnel__removed{position:absolute;left:9%;bottom:16%;display:flex;align-items:center;gap:6px;padding:5px 7px;background:#eee3f4;color:#716775;font:8px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.04em;text-transform:uppercase}
.ac-signal-funnel__removed>span{display:block;width:3px;height:3px;background:var(--ac-signal-accent)}
.ac-signal-funnel__footer{display:flex;align-items:center;justify-content:space-between;gap:10px 22px;flex-wrap:wrap;padding:15px 24px;border-top:1px solid var(--ac-signal-line);color:var(--ac-signal-muted);font:9px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace}
.ac-signal-funnel__footer>span:first-child{display:flex;align-items:center;gap:8px;color:var(--ac-signal-ink)}
.ac-signal-funnel__footer i{width:4px;height:4px;background:var(--ac-signal-accent)}
.ac-signal-funnel__sr{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
@container (width < 600px){
  .ac-signal-funnel__header{min-height:64px;padding:15px 17px;gap:12px}.ac-signal-funnel__header h2{font-size:11px;gap:8px}.ac-signal-funnel__motion{font-size:9px!important}
  .ac-signal-funnel__stage{height:500px}.ac-signal-funnel__fallback{inset:8% 15% 20%;clip-path:polygon(0 0,100% 0,50.5% 100%,49.5% 100%)}
  .ac-signal-funnel__input{top:11px;left:50%;transform:translateX(-50%);white-space:nowrap;max-width:90%}.ac-signal-funnel__output{top:auto;bottom:12px;right:auto;left:50%;transform:translateX(-50%);max-width:90%;white-space:nowrap}
  .ac-signal-funnel__gate{left:13%;right:13%;top:var(--gate-y);bottom:auto;width:auto;height:0}.ac-signal-funnel__gate-line{inset:0 0 auto;border-left:0;border-top:1px solid #747368}.ac-signal-funnel__gate-line:before,.ac-signal-funnel__gate-line:after{top:-4px;bottom:auto}.ac-signal-funnel__gate-line:before{left:0}.ac-signal-funnel__gate-line:after{left:auto;right:0}
  .ac-signal-funnel__gate button{left:auto;right:-11px;bottom:12px;transform:none;font-size:10px;padding:7px 9px;background:#ddd0ff;box-shadow:0 0 0 5px var(--ac-signal-surface)}
  .ac-signal-funnel__stage:is([data-gates="4"],[data-gates="5"]) .ac-signal-funnel__gate:is([data-order="1"],[data-order="3"]) button{top:auto;bottom:12px}.ac-signal-funnel__gate-label{max-width:100px}
  .ac-signal-funnel__gate[data-enabled=false] .ac-signal-funnel__gate-line{border-left:0;border-top-style:dashed}.ac-signal-funnel__removed{left:16px;bottom:20%;font-size:7px;padding:4px 5px}.ac-signal-funnel__footer{padding:14px 17px;font-size:8px;gap:8px}
}
@media(prefers-reduced-motion:reduce){.ac-signal-funnel *{transition:none!important}}

/* Keep purple signals and gates; adapt the neutral canvas and controls. */
:where([data-theme="dark"], .dark) .ac-signal-funnel { --ac-signal-ink: #eeeee9; --ac-signal-muted: #b1b2ac; --ac-signal-line: #43453f; --ac-signal-surface: #1c1e1b; }
:where([data-theme="dark"], .dark) .ac-signal-funnel__gate button { color: #34372e; }
:where([data-theme="dark"], .dark) .ac-signal-funnel__gate[data-enabled="false"] button { color: var(--ac-signal-muted); }
:where([data-theme="dark"], .dark) .ac-signal-funnel__gate-line { border-color: #9b9b90; }
:where([data-theme="dark"], .dark) .ac-signal-funnel__output { border-color: #85877c; }
